[
  {
    "id": "xauusd_5m_archetype_8",
    "name": "Session Compression + Order Flow Imbalance",
    "concept": "Identifies high-probability breakout opportunities by combining session compression with order flow imbalance.",
    "instructions": "1. Calculate session compression using session_compression function. 2. Identify order flow imbalance using order_flow_imbalance function. 3. Entry: Bullish when session compression is above 0.7 and order flow imbalance is above 0.5. Bearish when session compression is below -0.7 and order flow imbalance is below -0.5. 4. Exit: Take profit at 1.5 times the average true range (ATR). Stop loss at 1.5 times the ATR in the opposite direction. 5. Session gating: Only trade during the first 30 minutes of the session."
  },
  {
    "id": "xauusd_5m_archetype_9",
    "name": "HTF Swing + Volume Profile Levels",
    "concept": "Utilizes higher timeframe swings and volume profile levels to identify potential reversal points.",
    "instructions": "1. Identify HTF swings using htf_swings function. 2. Identify volume profile levels using volume_profile_levels function. 3. Entry: Bullish when price touches a volume profile level above the previous swing high. Bearish when price touches a volume profile level below the previous swing low. 4. Exit: Take profit at the next swing level. Stop loss at the previous swing level. 5. Session gating: Only trade during the last 30 minutes of the session."
  },
  {
    "id": "xauusd_5m_archetype_10",
    "name": "Absorption Volume + ADX Trend Filter",
    "concept": "Combines absorption volume with ADX trend filter to identify strong continuation or reversal opportunities.",
    "instructions": "1. Identify absorption volume using absorption_volume function. 2. Calculate ADX trend filter using adx function. 3. Entry: Bullish when absorption volume is detected and ADX is above 25. Bearish when absorption volume is detected and ADX is below -25. 4. Exit: Take profit at 2 times the ATR. Stop loss at 1.5 times the ATR in the opposite direction. 5. Session gating: Only trade during the first and last 30 minutes of the session."
  },
  {
    "id": "xauusd_5m_archetype_11",
    "name": "HTF Order Blocks + Keltner Channels",
    "concept": "Uses higher timeframe order blocks and Keltner channels to identify potential breakout or reversal points.",
    "instructions": "1. Identify HTF order blocks using htf_order_blocks function. 2. Calculate Keltner channels using keltner_channels function. 3. Entry: Bullish when price breaks above the upper Keltner channel and touches an HTF order block. Bearish when price breaks below the lower Keltner channel and touches an HTF order block. 4. Exit: Take profit at the next order block. Stop loss at the previous order block. 5. Session gating: Only trade during the first and last 30 minutes of the session."
  },
  {
    "id": "xauusd_5m_archetype_12",
    "name": "Session VWAP + Hurst Exponent",
    "concept": "Combines session VWAP with Hurst exponent to identify potential breakout or reversal points.",
    "instructions": "1. Calculate session VWAP using vwap function. 2. Calculate Hurst exponent using hurst_exponent function. 3. Entry: Bullish when price breaks above the session VWAP and Hurst exponent is above 0.7. Bearish when price breaks below the session VWAP and Hurst exponent is below 0.3. 4. Exit: Take profit at 1.5 times the ATR. Stop loss at 1.5 times the ATR in the opposite direction. 5. Session gating: Only trade during the first and last 30 minutes of the session."
  },
  {
    "id": "xauusd_5m_archetype_13",
    "name": "HTF Trend Filter + Shannon Entropy",
    "concept": "Uses higher timeframe trend filter and Shannon entropy to identify potential breakout or reversal points.",
    "instructions": "1. Calculate HTF trend filter using htf_trend_filter function. 2. Calculate Shannon entropy using shannon_entropy function. 3. Entry: Bullish when HTF trend filter is above 0.5 and Shannon entropy is below 0.5. Bearish when HTF trend filter is below -0.5 and Shannon entropy is below 0.5. 4. Exit: Take profit at 1.5 times the ATR. Stop loss at 1.5 times the ATR in the opposite direction. 5. Session gating: Only trade during the first and last 30 minutes of the session."
  },
  {
    "id": "xauusd_5m_archetype_14",
    "name": "Session Compression + Volatility Ratio",
    "concept": "Combines session compression with volatility ratio to identify potential breakout or reversal points.",
    "instructions": "1. Calculate session compression using session_compression function. 2. Calculate volatility ratio using volatility_ratio function. 3. Entry: Bullish when session compression is above 0.7 and volatility ratio is above 1.2. Bearish when session compression is below -0.7 and volatility ratio is below 0.8. 4. Exit: Take profit at 1.5 times the ATR. Stop loss at 1.5 times the ATR in the opposite direction. 5. Session gating: Only trade during the first and last 30 minutes of the session."
  }
]

[
  {
    "id": "XAUUSD_5m_1",
    "name": "Hurst Exponent Regime Filter with Keltner Channel Breakout",
    "concept": "Identify mean-reverting or trending regimes using Hurst Exponent and execute breakouts from Keltner Channels.",
    "instructions": "1. Calculate Hurst Exponent on 1-hour candles. 2. If Hurst Exponent > 0.5, market is trending; if < 0.5, mean-reverting. 3. Calculate Keltner Channels with 20-period ATR. 4. In trending regime, enter long on close above upper band, exit on close below lower band. 5. In mean-reverting regime, enter long on close above upper band, exit on close below lower band. 6. Use session_mask to gate trades to 9:30-16:00 EST. 7. Set SL at 1.5x ATR, TP at 3x ATR."
  },
  {
    "id": "XAUUSD_5m_2",
    "name": "Shannon Entropy Volatility Regime with Bollinger Band Squeeze",
    "concept": "Use Shannon Entropy to identify high-volatility regimes and execute trades in Bollinger Band squeezes.",
    "instructions": "1. Calculate Shannon Entropy on 5-minute candles over a 20-period window. 2. If Shannon Entropy > 0.5, market is in high-volatility regime. 3. Calculate Bollinger Bands with 20-period SMA and 2 standard deviations. 4. In high-volatility regime, enter long on close above upper band when bands are squeezing (distance between bands < 0.5% of price). 5. Exit on close below lower band or when bands stop squeezing. 6. Use session_mask to gate trades to 9:30-16:00 EST. 7. Set SL at 1.5x band width, TP at 3x band width."
  },
  {
    "id": "XAUUSD_5m_3",
    "name": "ADX Trend Strength Filter with Donchian Channel Breakout",
    "concept": "Filter trades based on ADX trend strength and execute breakouts from Donchian Channels.",
    "instructions": "1. Calculate ADX with 14-period SMA. 2. If ADX > 25, market is in a trend. 3. Calculate Donchian Channels with 20-period high/low. 4. In trending market, enter long on close above upper band, exit on close below lower band. 5. Use session_mask to gate trades to 9:30-16:00 EST. 6. Set SL at 1.5x channel range, TP at 3x channel range."
  },
  {
    "id": "XAUUSD_5m_4",
    "name": "Z-Score Mean Reversion with Chandelier Exit",
    "concept": "Use Z-Score to identify mean-reverting opportunities and manage risk with Chandelier Exit.",
    "instructions": "1. Calculate Z-Score of 5-minute closes over a 20-period window. 2. If Z-Score > 1.5, market is overbought; if < -1.5, market is oversold. 3. Enter long on close when Z-Score < -1.5, exit on close when Z-Score > 1.5. 4. Use Chandelier Exit with 22-period ATR to manage risk. 5. Use session_mask to gate trades to 9:30-16:00 EST. 6. Set SL at Chandelier Exit, TP at 2x ATR."
  },
  {
    "id": "XAUUSD_5m_5",
    "name": "Linear Regression Slope Trend Following with RVol Filter",
    "concept": "Follow trends using Linear Regression Slope and filter trades based on RVol.",
    "instructions": "1. Calculate Linear Regression Slope on 5-minute closes over a 20-period window. 2. If slope > 0.5, market is in an uptrend; if < -0.5, market is in a downtrend. 3. Calculate RVol over a 20-period window. 4. In uptrend, enter long on close when RVol > 1.5. 5. In downtrend, enter short on close when RVol > 1.5. 6. Use session_mask to gate trades to 9:30-16:00 EST. 7. Set SL at 1.5x RVol, TP at 3x RVol."
  },
  {
    "id": "XAUUSD_5m_6",
    "name": "Efficiency Ratio Regime Filter with Supertrend Breakout",
    "concept": "Identify trending or ranging regimes using Efficiency Ratio and execute breakouts from Supertrend.",
    "instructions": "1. Calculate Efficiency Ratio on 5-minute candles over a 20-period window. 2. If Efficiency Ratio > 0.7, market is trending; if < 0.3, market is ranging. 3. Calculate Supertrend with 10-period ATR. 4. In trending regime, enter long on close above Supertrend, exit on close below Supertrend. 5. In ranging regime, enter long on close above Supertrend, exit on close below Supertrend. 6. Use session_mask to gate trades to 9:30-16:00 EST. 7. Set SL at 1.5x ATR, TP at 3x ATR."
  },
  {
    "id": "XAUUSD_5m_7",
    "name": "Volatility Ratio Regime Filter with Volume Profile Breakout",
    "concept": "Identify high-volatility regimes using Volatility Ratio and execute breakouts from Volume Profile levels.",
    "instructions": "1. Calculate Volatility Ratio on 1-hour candles. 2. If Volatility Ratio > 1.5, market is in high-volatility regime. 3. Calculate Volume Profile levels on 5-minute candles. 4. In high-volatility regime, enter long on close above POC (Point of Control), exit on close below POC. 5. Use session_mask to gate trades to 9:30-16:00 EST. 6. Set SL at 1.5x POC distance, TP at 3x POC distance."
  },
  {
    "id": "XAUUSD_5m_8",
    "name": "Order Flow Imbalance Regime Filter with MACD Acceleration",
    "concept": "Identify high-order flow imbalance regimes and execute trades based on MACD acceleration.",
    "instructions": "1. Calculate Order Flow Imbalance on 5-minute candles. 2. If Order Flow Imbalance > 0.5, market is in high-buy pressure regime. 3. Calculate MACD with 12, 26, 9 periods. 4. In high-buy pressure regime, enter long on close when MACD line crosses above signal line, exit on close when MACD line crosses below signal line. 5. Use session_mask to gate trades to 9:30-16:00 EST. 6. Set SL at 1.5x MACD difference, TP at 3x MACD difference."
  }
]
